97	    }
98	
99	    public void setRegistrationDate(LocalDate registrationDate) {
100	        this.registrationDate = registrationDate;
101	    }
102	
103	    public String getCustomerCode() {
104	        return this.customerCode;
105	    }
106	
107	    public void setCustomerCode(String customerCode) {
108	        this.customerCode = customerCode;
109	    }
110	
111	    /**
112	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
113	     */
114	    @Transient
115	    public String getDisplayName() {
116	        return this.getLastName() + ", " + this.getFirstName();
117	    }
118	
119	    /**
120	     * The owner's initials: the upper-cased first letters of the first and last name,
121	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
122	     */
123	    @Transient
124	    public String getInitials() {
125	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
126	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
127	    }
128	
129	    protected Set<Pet> getPetsInternal() {
130	        if (this.pets == null) {
131	            this.pets = new HashSet<>();
132	        }
133	        return this.pets;
134	    }
135	
136	    protected void setPetsInternal(Set<Pet> pets) {
137	        this.pets = pets;
138	    }
139	
140	    public List<Pet> getPets() {
141	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
142	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
143	        return Collections.unmodifiableList(sortedPets);
