152	        pet.setOwner(this);
153	    }
154	
155	    /**
156	     * Return the Pet with the given name, or null if none found for this Owner.
157	     *
158	     * @param name to test
159	     * @return true if pet name is already in use
160	     */
161	    public Pet getPet(String name) {
162	        return getPet(name, false);
163	    }
164	
165	    /**
166	     * Return the Pet with the given name, or null if none found for this Owner.
167	     *
168	     * @param name to test
169	     * @return true if pet name is already in use
170	     */
171	    public Pet getPet(String name, boolean ignoreNew) {
172	        name = name.toLowerCase();
173	        for (Pet pet : getPetsInternal()) {
174	            if (!ignoreNew || !pet.isNew()) {
175	                String compName = pet.getName();
176	                compName = compName.toLowerCase();
177	                if (compName.equals(name)) {
178	                    return pet;
179	                }
